const tabId = 343605414;
const examPdfUrl = "https://otptat.ohio.gov/wps/wcm/connect/gov/425dac11-0be5-4871-8fec-346b20bae721/PYT_AT+EXAM_ELIC+PACKET+DEC+2025.pdf?MOD=AJPERES&CONVERT_TO=url&CACHEID=ROOTWORKSPACE.Z18_K9I401S01H7F40QBNJU3SO1F56-425dac11-0be5-4871-8fec-346b20bae721-pIfwymu";

const endorsePdfUrl = "https://otptat.ohio.gov/wps/wcm/connect/gov/4f7020c6-40f4-44ef-8d97-c81e29840932/PYT_AT+ENDORSE_ELIC+PACKET+DEC+2025.pdf?MOD=AJPERES&CONVERT_TO=url&CACHEID=ROOTWORKSPACE.Z18_K9I401S01H7F40QBNJU3SO1F56-4f7020c6-40f4-44ef-8d97-c81e29840932-pIfwTOq";

const parsePdf = async (url) => {
  return await browserjs(tabId, async (url) => {
    // Load pdf.js dynamically in page
    if (!window.pdfjsLib) {
      await new Promise((resolve, reject) => {
        const script = document.createElement('script');
        script.src = 'https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.min.js';
        script.onload = resolve;
        script.onerror = reject;
        document.head.appendChild(script);
      });
      window.pdfjsLib.GlobalWorkerOptions.workerSrc = 'https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js';
    }

    const resp = await fetch(url);
    const arrayBuffer = await resp.arrayBuffer();
    const pdf = await window.pdfjsLib.getDocument({ data: arrayBuffer }).promise;

    let text = '';
    for (let i = 1; i <= pdf.numPages; i++) {
      const page = await pdf.getPage(i);
      const content = await page.getTextContent();
      const strings = content.items.map(item => item.str);
      text += `--- PAGE ${i} ---\n` + strings.join(' ') + '\n\n';
    }
    return text;
  }, url);
};

const examText = await parsePdf(examPdfUrl);
console.log("EXAM TEXT PREVIEW:");
console.log(examText.slice(0, 3000));

